 # -*- coding: utf-8 -*-"""Name: Anatoliy LevchukVersion: 1.5Date: 08-08-2025Email: feuerlag999@yandex.ruGitHub: https://github.com/LeTond"""import osimport sysimport cv2import yamlimport torchimport platformimport numpy as npimport pandas as pdimport albumentations as Aimport torch.nn.functional as Fimport torchvision.transforms as transformsimport torchvision.transforms.functional as TFfrom torch import nnfrom torchsummary import summaryimport CardioCascadeNetclass MetaParameters:    _root_directory_path = os.path.abspath(os.path.dirname('..'))    config_path = f"{_root_directory_path}/config.yml"    with open(config_path, 'r') as stream:        _project_config = yaml.safe_load(stream)['almaz_model']['project_config']    with open(config_path, 'r') as stream:        _meta_config = yaml.safe_load(stream)['almaz_model']['meta']    with open(config_path, 'r') as stream:        _hyperparams = yaml.safe_load(stream)['almaz_model']['network_hyperparams']    with open(config_path, 'r') as stream:        _class_weights = yaml.safe_load(stream)['almaz_model']['cardio_class_weights']    """ Initializing project configuration """    PROJECT_NAME, DATASET_NAME, FOLD_NAME = _project_config.values()        DATASET_DIR = f"{_root_directory_path}/Dataset/"    RESULTS_DIR = f"{_root_directory_path}/Results/"    """ Initializing meta """    FREEZE_BN, PRETRAIN, AUGMENTATION, NOISE, EMPTY, MULTYGAP, \    UNET1, UNET2, UNET3, UNET4, UNET5, BGCROPP, LVCROPP, BGLVCROPP, SHUFFLE = _meta_config.values()    AUGMENTATION = True    UNET1 = True    UNET2 = True    """ Initializing network_hyperparams """    KERNEL, CROPP_KERNEL, CHANNELS, LR, BT_SZ, EPOCHS, DROPOUT, FEATURES, \    WDC, EARLY_STOPPING, TMAX, CLIP_RATE, \    SCAR_DICT_CLASS, MYOLEVEL_DICT_CLASS, BULLEYE_DICT_CLASS = _hyperparams.values()    CLIP_RATE = None        """ Initializing cardio_class_weights """    BASE_MODEL_WEIGHT, CROPP_MODEL_WEIGHT, \    LV_CLASS_MODEL_WEIGHT, BULL_EYE_MODEL_WEIGHT = _class_weights.values()    TARGET_CE_WEIGHTS = torch.FloatTensor(BASE_MODEL_WEIGHT)    SCAR_CE_WEIGHTS = torch.FloatTensor(CROPP_MODEL_WEIGHT)    MYOLEVEL_CE_WEIGHTS = torch.FloatTensor(LV_CLASS_MODEL_WEIGHT)    BULLEYE_CE_WEIGHTS = torch.FloatTensor(BULL_EYE_MODEL_WEIGHT)    if UNET5 is True:        DICT_CLASS = BULLEYE_DICT_CLASS          CE_WEIGHTS = BULLEYE_CE_WEIGHTS    elif UNET4 is True and UNET5 is False:        DICT_CLASS = MYOLEVEL_DICT_CLASS        CE_WEIGHTS = MYOLEVEL_CE_WEIGHTS    elif UNET3 is True and UNET4 is False:        DICT_CLASS = SCAR_DICT_CLASS        CE_WEIGHTS = SCAR_CE_WEIGHTS    elif UNET2 is True and UNET3 is False:        DICT_CLASS = SCAR_DICT_CLASS        CE_WEIGHTS = SCAR_CE_WEIGHTS    elif UNET1 is True and UNET2 is False:        DICT_CLASS = SCAR_DICT_CLASS        CE_WEIGHTS = TARGET_CE_WEIGHTS    NUM_CLASS = len(DICT_CLASS)    """ NEW DIRECTORY_NAMES """    UNET1_FOLD = f'Unet1_Fold_{FOLD_NAME}/'    UNET2_FOLD = f'Unet2_Fold_{FOLD_NAME}/'    UNET3_FOLD = f'Unet3_Fold_{FOLD_NAME}/'    UNET4_FOLD = f'Unet4_Fold_{FOLD_NAME}/'    UNET5_FOLD = f'Unet5_Fold_{FOLD_NAME}/'    PROJ_NAME = f"{_root_directory_path}/{PROJECT_NAME}/Model/{DATASET_NAME}"    IMAGES_DIR = f'{DATASET_DIR}{DATASET_NAME}_images'    MASKS_DIR = f'{DATASET_DIR}{DATASET_NAME}_masks'    NEW_DATA_PATH = f'{DATASET_DIR}{DATASET_NAME}_images_new/'    NEW_UNET1_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet1_masks_new/'    NEW_UNET2_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet2_masks_new/'    NEW_UNET3_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet3_masks_new/'    NEW_UNET4_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet4_masks_new/'    NEW_UNET5_MASKS_PATH = f'{RESULTS_DIR}{DATASET_NAME}_Unet5_masks_new/'class ChooseDevice:    def __init__(self):        self.print_device    @staticmethod    def __device():        if torch.backends.mps.is_available():            device = torch.device('mps')        elif torch.cuda.is_available():            device = torch.device('cuda')        else:            device = torch.device('cpu')        return device    @property    def device(self):        return self.__device()    @property    def print_device(self):        print(self.device)class FocalLoss(nn.modules.loss._WeightedLoss):    def __init__(self, weight = None, gamma = 2, reduction = 'mean'):    #reduction='sum'        super(FocalLoss, self).__init__(weight,reduction = reduction)        self.gamma = gamma        self.weight = weight    def forward(self, input, target):        ce_loss = F.cross_entropy(input, target, reduction = self.reduction,weight = self.weight)        pt = torch.exp( - ce_loss)        focal_loss = ((1 - pt) ** self.gamma * ce_loss).mean()        return focal_lossclass ChooseKernelSize(MetaParameters):    def __init__(self):            super().__init__()    def matrix_size(self, unet_type = None):        if unet_type is None:            if self.UNET5 is True:                return 'cropp'            elif self.UNET4 is True and self.UNET5 is False:                return 'cropp'            elif self.UNET3 is True and self.UNET4 is False:                return 'close_cropp'            elif self.UNET2 is True and self.UNET3 is False:                return 'cropp'            elif self.UNET1 is True and self.UNET2 is False:                return 'default'            else:                 raise ValueError("Check UNET configuration. Make shure that all UNET MetaParameters before target UNET(N) is True")        else:            return unet_type    def kernel_size(self, unet_type = None):        matrix_size = self.matrix_size(unet_type)        if matrix_size == 'default':            return self.KERNEL        elif matrix_size == 'cropp':            return self.CROPP_KERNEL        elif matrix_size == 'close_cropp':            return self.CROPP_KERNEL        else:            raise ValueError("Check matrix size value. Make shure that input value is correct for chosen matrix preprocessing")class ChooseModelConfig(MetaParameters):    def __init__(self):            super(MetaParameters, self).__init__()        self.__model = self.choose_train_model      @property    def model(self):        return self.__model    @property      def choose_model_key(self):        if self.UNET5 is True:            return self.UNET5_FOLD        elif self.UNET4 is True and self.UNET5 is False:            return self.UNET4_FOLD        elif self.UNET3 is True and self.UNET4 is False:            return self.UNET3_FOLD        elif self.UNET2 is True and self.UNET3 is False:            return self.UNET2_FOLD        elif self.UNET1 is True and self.UNET2 is False:            return self.UNET1_FOLD        else:            raise ValueError("Check UNET configuration. Make shure that all UNET MetaParameters before target UNET(N) is True")    @property    def model_key(self):        return self.choose_model_key    @property    def choose_train_model(self):        if self.PRETRAIN:                try:                checkpoint = torch.load(f"{self.PROJ_NAME}/{self.DATASET_NAME}_model.pth")                # checkpoint = torch.load(f'{self.PROJ_NAME}/{self.DATASET_NAME}_model.pth', map_location = torch.device('cpu'))                checkpoint = checkpoint[f"Net_{self.DATASET_NAME}_{self.model_key}"]                model = checkpoint['Model']                model.load_state_dict(checkpoint['weights'])                  model.eval()                      print(f'model loaded: {self.DATASET_NAME}_model.pth')            except:                print('no trained models')                model = CardioCascadeNet.UNet_2D_AttantionLayer().to(device = device)                else:            model = CardioCascadeNet.UNet_2D_AttantionLayer().to(device = device)            # model = CardioCascadeNet.UNet_2D().to(device=device)            # model = CardioCascadeNet.UNetResnet().to(device=device)            # model = CardioCascadeNet.SegNet().to(device=device)            # model = CardioCascadeNet.ResNet().to(device=device)            # model = CardioCascadeNet.SwinUNet().to(device = device)            # model = CardioCascadeNet.R2AttU_Net().to(device = device)                return model    def summary_params(self):        summary(self.choose_train_model, input_size = (2, 64, 64))    @property    def freeze_model_bn(self):        if self.FREEZE_BN is True:            for name, child in self.model.named_children():                 # if name in ['bottleneck', 'decoder4', 'decoder3','decoder2', 'decoder1', 'upconv4', 'upconv3', 'upconv2', 'upconv1', 'conv', 'Att4', 'Att3', 'Att2', 'Att1']:                # if name in ['decoder4', 'decoder3','decoder2', 'decoder1', 'upconv4', 'upconv3', 'upconv2', 'upconv1', 'conv', 'Att4', 'Att3', 'Att2', 'Att1']:                # if name in ['bottleneck', 'decoder4', 'decoder3', 'decoder2', 'decoder1']:                if name in ['decoder4', 'upconv4', 'Att4', 'decoder3', 'upconv3', 'Att3', 'decoder2', 'upconv2', 'Att2', 'decoder1', 'upconv1', 'Att1', 'conv']:                # if name in ['decoder1', 'upconv1', 'Att1', 'conv']:                    print(name + ' has been unfrozen.')                     for param in child.parameters():                         param.requires_grad = True                 else:                     for param in child.parameters():                         param.requires_grad = False        # optimizer = torch.optim.Adam(filter(lambda x: x.requires_grad, self.model.parameters()), lr = self.LR, weight_decay = self.WDC)        # optimizer = torch.optim.Adam(self.model.parameters(), lr = self.LR, weight_decay = self.WDC)        # optimizer = torch.optim.AdamW(self.model.parameters(), lr = self.LR, weight_decay = self.WDC)        # optimizer = CardioCascadeNet.Lion(self.model.parameters(), lr = self.LR, betas = (0.9, 0.99), weight_decay = self.WDC)        # optimizer = torch.optim.AdamW(self.model.parameters(), lr = self.LR, weight_decay = self.WDC, amsgrad = False)        # optimizer = torch.optim.SGD(self.model.parameters(), lr = self.LR, weight_decay = self.WDC, momentum = 0.9, nesterov = True)        optimizer = CardioCascadeNet.Ranger(self.model.parameters(), lr = self.LR, k = 6, N_sma_threshhold = 5, weight_decay = self.WDC)        # optimizer = CardioCascadeNet.Ranger(filter(lambda x: x.requires_grad, self.model.parameters()),  lr = self.LR, k = 6, N_sma_threshhold = 5, weight_decay = self.WDC)        return optimizer    @property    def optimizer(self):        return self.freeze_model_bn    @property    def choose_scheduler_gen(self):        scheduler_gen = torch.optim.lr_scheduler.CosineAnnealingLR(            self.optimizer, T_max = self.TMAX, eta_min = 0, last_epoch = -1, verbose = True)        # scheduler_gen = torch.optim.lr_scheduler.ReduceLROnPlateau(        #     optimizer, mode = 'min', factor = 0.8, patience = 5, threshold = 0.0001, threshold_mode = 'rel',         #     cooldown = 0, min_lr = 0, eps = 1e-08, verbose = 'deprecated')        return scheduler_gen    @property    def scheduler_gen(self):        return self.choose_scheduler_gen    @staticmethod    def __rewrite_weights(from_model, to_model, unet_model):        _root_directory_path = os.path.abspath(os.path.dirname('..'))                ##############################################################################        checkpoint1 = torch.load(f"{_root_directory_path}/CardioCascadeNet/Results/{from_model}/{from_model}_model.pth")        checkpoint1 = checkpoint1[f'Net_{from_model}_{unet_model}']        ##############################################################################                # checkpoint1 = torch.load(f"{_root_directory_path}/CardioCascadeNet/Results/Unet2_Fold_05/model_best.pth").to(device=device)        ##############################################################################        model = checkpoint1['Model']        model.load_state_dict(checkpoint1['weights'])          project_name = f'{_root_directory_path}/CardioCascadeNet/Results/{unet_model}'        torch.save(model, f'{project_name}/model_best.pth')        ##############################################################################                # checkpoint = torch.load(f"{_root_directory_path}/CardioCascadeNet/Results/{to_model}/{to_model}_model.pth")        # checkpoint[f'Net_{to_model}_{unet_model}'] = {'Model': checkpoint1, 'weights': checkpoint1.state_dict()}        # torch.save(        #     checkpoint,        #     f"{_root_directory_path}/CardioCascadeNet/Results/{to_model}/{to_model}_model.pth")        # print(f'weights was pull from {from_model} and drop to {to_model}')        # checkpoint[f'Net_{to_model}_{unet_model}'] = {'Model': checkpoint1['Model'], 'weights': checkpoint1['Model'].state_dict()}    @staticmethod    def rewrite_weights(from_model, to_model, unet_model):        _root_directory_path = os.path.abspath(os.path.dirname('..'))        checkpoint1 = torch.load(f"{_root_directory_path}/CardioCascadeNet/Results/{from_model}/{from_model}_model.pth")        checkpoint1 = checkpoint1[f'Net_{from_model}_{unet_model}']                checkpoint = torch.load(f"{_root_directory_path}/CardioCascadeNet/Results/{to_model}/{to_model}_model.pth")        checkpoint[f'Net_{to_model}_{unet_model}'] = {'Model': checkpoint1['Model'], 'weights': checkpoint1['Model'].state_dict()}                torch.save(            checkpoint,            f"{_root_directory_path}/CardioCascadeNet/Results/{to_model}/{to_model}_model.pth")        print(f'weights was pull from {from_model} and drop to {to_model}')class ChooseLossFunction(MetaParameters):    def __init__(self):        super(MetaParameters, self).__init__()        self.print_loss_function()            @property    def choose_loss_function(self):        try:            loss_function = nn.CrossEntropyLoss(weight = self.CE_WEIGHTS).to(device)            # loss_function = FocalLoss(weight = self.CE_WEIGHTS).to(device)                        return loss_function        except:            loss_function = FocalLoss().to(device)                        return loss_function    @property    def loss_function(self):        return self.choose_loss_function    def print_loss_function(self):        if self.CE_WEIGHTS is not None:            print(f'{self.loss_function} With {self.CE_WEIGHTS} Was Chosen !!!')        else:                        print(f'{self.loss_function} without CE_WEIGHTS Was Chosen !!!')class ChooseTransform(MetaParameters):    def __init__(self):        super(MetaParameters, self).__init__()    @classmethod    def choose_transforms(cls, transform):        transform_01 = transforms.Compose([            transforms.ToPILImage(),            transforms.ToTensor(),        ])        transform_02 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomRotation((-5, 5), expand = False),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.ToTensor(),        ])        transform_03 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.RandomAffine(degrees = (-2, 2), translate = (0.05, 0.15), scale = (0.95, 1.05)),            transforms.ToTensor(),        ])        transform_04 = A.Compose(A.ElasticTransform(alpha = 20, sigma = 50, alpha_affine = 8,                                   interpolation = cv2.INTER_NEAREST, border_mode = cv2.BORDER_CONSTANT, value = None,                                   mask_value = None, always_apply = False, approximate = False, p = 1))        transform_05 = A.Compose(A.GridDistortion(num_steps = 10, distort_limit = 0.05, interpolation = cv2.INTER_NEAREST,                                    border_mode = cv2.BORDER_CONSTANT, value = None, mask_value = None,                                    always_apply = False, p = 1))        transform_06 = transforms.Compose([            transforms.ToPILImage(),            transforms.RandomRotation((-5, 5), expand = False),            transforms.RandomHorizontalFlip(0.5),            transforms.RandomVerticalFlip(0.5),            transforms.RandomAffine(degrees = (-8, 8), translate = (0.05, 0.15), scale = (0.9, 1.1)),            transforms.ToTensor(),        ])        transform_dict = {        'transform_01': transform_01, 'transform_02': transform_02, 'transform_03': transform_03,        'transform_04': transform_04, 'transform_05': transform_05, 'transform_06': transform_06,        }        return transform_dict[transform]    def aug_transforms(self):        return [            # A.VerticalFlip(p=1),            # A.HorizontalFlip(p=1),            # A.Rotate(limit=(-90, 90), interpolation=cv2.INTER_NEAREST, border_mode=cv2.BORDER_CONSTANT, value=None, mask_value=None,                     # always_apply=False, p=1),            A.ElasticTransform(alpha = 20, sigma = 50, alpha_affine = 8,                               interpolation = cv2.INTER_NEAREST, border_mode = cv2.BORDER_CONSTANT, value = None,                               mask_value = None, always_apply = False, approximate = False, p = 1),            # A.Crop(0, 40, 100, 144),            # A.Crop(40, 40, 140, 144),            # A.Crop(0, 0, 144, 144),            # A.Crop(10, 20, 144, 144)                        # A.RandomBrightnessContrast()            # A.GridDistortion(num_steps = 20, distort_limit = 0.2, interpolation = cv2.INTER_NEAREST,            #                     border_mode = cv2.BORDER_CONSTANT, value = None, mask_value = None,            #                     always_apply = False, p = 1)        ]device = ChooseDevice().deviceprint(f"Python Platform: {platform.platform()}")print(f'python version: {sys.version}')print(f'torch version: {torch.__version__}')print(f'numpy version: {np.__version__}')print(f'pandas version: {pd.__version__}')